--- a/internal/cache/client.go
+++ b/internal/cache/client.go
@@ -2,18 +2,42 @@ package cache

 import (
 	"errors"
+	"math/rand"
 	"time"
 )

 var ErrUnavailable = errors.New("cache unavailable")

+// maxAttempts and maxBackoff stay bounded to prevent unbounded retry storms.
+// INC-2019-07 documents that an uncapped retry loop drove 40x load and caused
+// a 52-minute outage when the cache rebooted (docs/postmortems/INC-2019-07.md).
+// Do not remove the cap.
+const (
+	maxAttempts = 8
+	baseBackoff = 50 * time.Millisecond
+	maxBackoff  = 500 * time.Millisecond
+)
+
 func (c *Client) Get(key string) ([]byte, error) {
-	for attempt := 0; attempt < 5; attempt++ {
+	for attempt := 0; attempt < maxAttempts; attempt++ {
 		v, err := c.conn.Get(key)
 		if err == nil {
 			return v, nil
 		}
-		time.Sleep(time.Duration(attempt*attempt) * 50 * time.Millisecond)
+
+		if attempt == maxAttempts-1 {
+			break
+		}
+
+		backoff := time.Duration(attempt*attempt) * baseBackoff
+		if backoff > maxBackoff {
+			backoff = maxBackoff
+		}
+		// Full jitter: add random delay up to baseBackoff to desynchronize
+		// concurrent callers and avoid thundering-herd waves during load spikes.
+		jitter := time.Duration(rand.Int63n(int64(baseBackoff)))
+		time.Sleep(backoff + jitter)
 	}
 	return nil, ErrUnavailable
 }
+

