 export const VISIBILITY_TIMEOUT_S = 300;

-export async function consume(handler: (m: unknown) => Promise<void>) {
+// How often a live worker renews visibility while processing. Must stay well under
+// VISIBILITY_TIMEOUT_S so a renewal occurs before the timeout expires. When a worker
+// crashes, the heartbeat stops and the message becomes visible again for another worker
+// without risking duplicate delivery during legitimate long-running processing (see Q-58).
+export const HEARTBEAT_INTERVAL_S = 30;
+
+export type ExtendVisibilityFn = (seconds: number) => Promise<void>;
+
+/**
+ * Starts a heartbeat timer that periodically extends the message visibility timeout
+ * while the worker is actively processing. Returns a function to stop the heartbeat.
+ */
+export function startHeartbeat(
+  extendVisibility: ExtendVisibilityFn,
+  intervalSeconds: number = HEARTBEAT_INTERVAL_S,
+): () => void {
+  const timer = setInterval(() => {
+    extendVisibility(VISIBILITY_TIMEOUT_S).catch(() => {});
+  }, intervalSeconds * 1000);
+  return () => clearInterval(timer);
