 // the timeout while processing, do not lower the number.
 export const VISIBILITY_TIMEOUT_S = 300;

+// How often the heartbeat renews the visibility window while a message is being processed.
+// Must be well under VISIBILITY_TIMEOUT_S so a single missed beat does not expire the lease.
+// When a worker crashes the heartbeat stops, and the message becomes visible again after at
+// most HEARTBEAT_INTERVAL_MS milliseconds rather than the full VISIBILITY_TIMEOUT_S window
+// — that is the fix for Q-58.
+export const HEARTBEAT_INTERVAL_MS = 30_000;
+
+/**
+ * Extend the visibility timeout for `messageId` every HEARTBEAT_INTERVAL_MS while the
+ * returned stop function has not been called. Call stop() when processing finishes (or throws)
+ * to cancel the interval immediately.
+ */
+export function startHeartbeat(
+  extendVisibility: (messageId: string, timeoutSeconds: number) => Promise<void>,
+  messageId: string,
+): () => void {
+  const timer = setInterval(() => {
+    extendVisibility(messageId, VISIBILITY_TIMEOUT_S).catch(() => {
+      // Heartbeat failures are non-fatal: the next beat will retry, and the
+      // original timeout is long enough to cover several missed beats.
+    });
+  }, HEARTBEAT_INTERVAL_MS);
+
+  return () => clearInterval(timer);
+}
+
 export async function consume(handler: (m: unknown) => Promise<void>) {
   // processing takes up to 240 s for large batches
